  ],
  "keyInsight": "Both models give the same end result — a tightly matched enzyme–substrate complex — but lock-and-key assumes the match exists beforehand, while induced fit says the substrate itself sculpts the active site into its complementary shape.",
  "reconstructionNotes": "Two side-by-side panels sharing a common style. Enzyme: broad rounded dome with flat-ish bottom, pale yellow-green fill, heavy olive-green stroke, word 'Enzyme' centered below. Active site is a small double-notch cleft at the top center with a central ridge. Substrates: two lavender shapes with black outlines — left one squarish with a downward stem, right one circular with a stepped notch — each ending in a small tan/peach binding knob; label 'Substrates' above with thin leader lines. In the unbound frame show curved black arrows from the annotation text down into the cleft, with text 'Active site is proper shape' (lock-and-key) or 'Active site changes to fit' (induced fit). In the bound frame, substrates sit in the cleft, a bold black vertical line marks the substrate–substrate interface and short bold black segments mark the substrate–enzyme contacts, with 'Substrate complex formed' above. Panel captions '(a) Lock-and-key model' and '(b) Induced fit model' centered beneath. When the model toggle is set to induced fit, the unbound cleft should be visibly wider and shallower than the bound cleft; in lock-and-key the cleft geometry must be pixel-identical between unbound and bound states. The ghost overlay is a grey dashed copy of the unbound active-site contour drawn over the bound enzyme. Interpolate substrate position and (for induced fit only) the cleft control points smoothly with the docking slider."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="display:block;font-weight:bold;font-size:12px">Enzyme binding models</span>
<label><input id="modelToggleInput" type="checkbox" onchange="toggle_modelToggle(this.checked)"> Binding model: <span id="modelName">Lock-and-key (a)</span></label>
<span id="deltaReadout" style="display:block;font-size:11px;color:#555">Conformational change on binding: <b>none</b></span>
<label>Substrate docking progress: <output id="bindingProgressVal">0</output><input id="bindingProgressInput" type="range" min="0" max="1" step="0.01" value="0" oninput="document.getElementById('bindingProgressVal').value=this.value;update_bindingProgress(+this.value)"></label>
<label><input id="shapeGhostInput" type="checkbox" onchange="toggle_shapeGhost(this.checked)"> Show unbound active-site outline</label>
<button id="playBtn" onclick="trigger_playBinding()">▶ Play substrate binding</button>
<span style="display:block;border-top:1px solid #dcdfe3;margin-top:5px;padding-top:5px;font-weight:bold" id="stepTitle">Guided demo</span>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;color:#333">Use ◀ ▶ to walk through the six guided steps.</span>
<span style="display:flex;gap:8px;align-items:center"><button onclick="prevStep()">◀</button><span id="stepLabel">Step 1 / 6</span><button onclick="nextStep()">▶</button></span>
<button onclick="showPopup('Key insight','Both models end with the same tightly matched enzyme–substrate complex. Lock-and-key assumes the complementary shape already exists before binding; induced fit says the arriving substrate itself sculpts the active site into that complementary shape.')">Key insight</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var VW = 760, VH = 350;
  draw.viewbox(0, 0, VW, VH);

  var C = {
    enzFill: '#e9f1cb', enzStroke: '#8fb440',
    subFill: '#cbbde4', subStroke: '#231f20',
    knob: '#e7b797', text: '#231f20', ghost: '#8c8c8c', accent: '#7fb0d8'
  };
  var S = 190, BY = 278;

  var dyn = draw.group();

  var diagrams = [
    { cx: 107, mode: 'lock', dock: true },
    { cx: 291, mode: 'lock', dock: false },
    { cx: 483, mode: 'fit', dock: true },
    { cx: 673, mode: 'fit', dock: false }
  ];

  var state = { model: 'Lock-and-key', progress: 0, ghost: false };

  function lerp(a, b, t) { return a + (b - a) * t; }
  function clamp(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
  function ease(t) { t = clamp(t); return t * t * (3 - 2 * t); }
  function r1(v) { return Math.round(v * 10) / 10; }

  /* ---------- active-site geometry ---------- */
  function cleftParams(m) {
    return {
      CW: lerp(30, 21, m),
      rw: lerp(6, 3, m),
      pd: lerp(11, 20, m),
      rt: lerp(8, 4, m),
      pd2: lerp(10, 18, m)
    };
  }

  function cleftSeg(cx, p) {
    var CW = p.CW, rw = p.rw, pd = p.pd, rt = p.rt, pd2 = p.pd2, s = '';
    s += ' L ' + r1(cx - CW) + ' ' + r1(S + pd - 6);
    s += ' Q ' + r1(cx - CW) + ' ' + r1(S + pd) + ' ' + r1(cx - CW + 5) + ' ' + r1(S + pd);
    s += ' L ' + r1(cx - rw - 3) + ' ' + r1(S + pd);
    s += ' Q ' + r1(cx - rw) + ' ' + r1(S + pd) + ' ' + r1(cx - rw) + ' ' + r1(S + pd - 6);
    s += ' L ' + r1(cx - rw) + ' ' + r1(S + rt);
    s += ' Q ' + r1(cx) + ' ' + r1(S + rt - 3) + ' ' + r1(cx + rw) + ' ' + r1(S + rt);
    s += ' L ' + r1(cx + rw) + ' ' + r1(S + pd2 - 6);
    s += ' Q ' + r1(cx + rw) + ' ' + r1(S + pd2) + ' ' + r1(cx + rw + 3) + ' ' + r1(S + pd2);
    s += ' L ' + r1(cx + CW - 5) + ' ' + r1(S + pd2);
    s += ' Q ' + r1(cx + CW) + ' ' + r1(S + pd2) + ' ' + r1(cx + CW) + ' ' + r1(S + pd2 - 6);
    s += ' L ' + r1(cx + CW) + ' ' + S;
    return s;
  }

  function enzymePath(cx, p) {
    var CW = p.CW, q = (58 + CW) / 2;
    return 'M ' + (cx - 81) + ' ' + (BY - 14) +
      ' C ' + (cx - 81) + ' ' + (S + 34) + ' ' + (cx - 76) + ' ' + (S + 12) + ' ' + (cx - 58) + ' ' + (S + 5) +
      ' Q ' + r1(cx - q) + ' ' + (S + 1) + ' ' + r1(cx - CW) + ' ' + S +
      cleftSeg(cx, p) +
      ' Q ' + r1(cx + q) + ' ' + (S + 1) + ' ' + (cx + 58) + ' ' + (S + 5) +
      ' C ' + (cx + 76) + ' ' + (S + 12) + ' ' + (cx + 81) + ' ' + (S + 34) + ' ' + (cx + 81) + ' ' + (BY - 14) +
      ' Q ' + (cx + 81) + ' ' + BY + ' ' + (cx + 69) + ' ' + BY +
      ' L ' + (cx - 69) + ' ' + BY +
      ' Q ' + (cx - 81) + ' ' + BY + ' ' + (cx - 81) + ' ' + (BY - 14) + ' Z';
  }

  function ghostPath(cx, p) {
    return 'M ' + r1(cx - p.CW - 14) + ' ' + (S - 1) + ' L ' + r1(cx - p.CW) + ' ' + S +
      cleftSeg(cx, p) + ' L ' + r1(cx + p.CW + 14) + ' ' + (S - 1);
  }

  /* ---------- substrate silhouettes (origin = bottom of tan knob) ---------- */
  var LEFT_BODY = 'M 15 -24 L 15 -63 Q 15 -70 8 -70 L -27 -70 Q -34 -70 -34 -63 ' +
    'L -34 -31 Q -34 -24 -27 -24 L -7 -24 L -7 -16 L 7 -16 L 7 -24 Z';
  var LEFT_KNOB = 'M -8 -17 L 8 -17 L 8 -7 Q 8 0 0 0 Q -8 0 -8 -7 Z';
  var RIGHT_BODY = 'M -9 -16 L -9 -48 C -9 -76 6 -88 20 -81 C 32 -75 33 -53 20 -45 ' +
    'C 15 -42 11 -41 9 -39 L 9 -16 Z';
  var RIGHT_KNOB = 'M -8 -17 L 8 -17 L 4 -6 Q 0 0 -4 -6 Z';

  function substrate(g, bodyD, knobD, x, y, tip) {
    var grp = g.group().transform({ translate: [r1(x), r1(y)] });
    grp.path(bodyD).fill(C.subFill).stroke({ color: C.subStroke, width: 1.9, linejoin: 'round' });
    grp.path(knobD).fill(C.knob).stroke({ color: C.subStroke, width: 1.4, linejoin: 'round' });
    grp.css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip(tip, ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Substrate',
          'Substrates are the reactant molecules an enzyme acts on. The small tan knob is the binding face that must match the contour of the active site; specificity comes from this complementary fit.');
      });
    return grp;
  }

  function txt(g, s, x, y, size, halo, weight) {
    var t = g.plain(s)
      .font({ family: 'sans-serif', size: size, anchor: 'middle', weight: weight || 'normal' })
      .fill(C.text).attr({ x: r1(x), y: r1(y) });
    if (halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }

  function arrowHead(g, x, y, ang) {
    var L = 11, Wd = 5.2;
    var pts = [
      [x, y],
      [x - L * Math.cos(ang) + Wd * Math.sin(ang), y - L * Math.sin(ang) - Wd * Math.cos(ang)],
      [x - L * Math.cos(ang) - Wd * Math.sin(ang), y - L * Math.sin(ang) + Wd * Math.cos(ang)]
    ];
    g.polygon(pts.map(function (p) { return r1(p[0]) + ',' + r1(p[1]); }).join(' ')).fill(C.text);
  }

  /* ---------- one diagram ---------- */
  function drawDiagram(d) {
    var g = dyn.group();
    var cx = d.cx;
    var t = d.dock ? state.progress : 1;
    var e = ease(t);
    var m = (d.mode === 'fit') ? e : 1;
    var p = cleftParams(m);

    var enz = g.path(enzymePath(cx, p))
      .fill(C.enzFill).stroke({ color: C.enzStroke, width: 4.2, linejoin: 'round' });
    enz.css('cursor', 'pointer')
      .on('mousemove', function (ev) {
        showTooltip(d.mode === 'fit'
          ? 'Enzyme (induced fit): the cleft reshapes as the substrate arrives'
          : 'Enzyme (lock-and-key): the cleft keeps one rigid shape', ev);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Enzyme and active site',
          'The enzyme is a large protein; the notched cleft on its upper surface is the active site where catalysis happens. In the lock-and-key model this cleft is rigid and pre-shaped; in the induced-fit model it is flexible and molds around the substrate.');
      });

    // invisible hover target over the cleft (below the substrates)
    g.rect(2 * p.CW + 12, 34).move(cx - p.CW - 6, S - 8).fill({ color: '#fff', opacity: 0 })
      .css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('Active site — the notched cleft with a central ridge', ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Active site',
          'The active site is a small pocket built from a few amino-acid side chains. Its shape and chemistry decide which substrates can bind — this is the structural basis of enzyme specificity.');
      });

    // ghost of the unbound active-site contour
    if (state.ghost) {
      var p0 = cleftParams(d.mode === 'fit' ? 0 : 1);
      var gh = g.path(ghostPath(cx, p0)).fill('none')
        .stroke({ color: C.ghost, width: 1.9, dasharray: '5,3.5', linejoin: 'round' });
      gh.css('cursor', 'pointer')
        .on('mousemove', function (ev) {
          showTooltip(d.mode === 'fit'
            ? 'Unbound active-site outline — wider and shallower than the bound shape'
            : 'Unbound active-site outline — identical to the bound shape', ev);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Conformational change',
            'The grey dashed line is the shape of the active site before any substrate arrives. In lock-and-key it lies exactly on the bound contour (no change). In induced fit it sits outside the bound contour, measuring how far the enzyme bent to wrap the substrate.');
        });
    }

    // substrates: unbound → docked
    var lx = lerp(cx - 64, cx - 12.5, e), ly = lerp(S - 52, S + 20, e);
    var rx = lerp(cx + 56, cx + 12.5, e), ry = lerp(S - 40, S + 18, e);
    substrate(g, LEFT_BODY, LEFT_KNOB, lx, ly, 'Substrate 1 — stepped square lobe with a tan binding knob');
    substrate(g, RIGHT_BODY, RIGHT_KNOB, rx, ry, 'Substrate 2 — round lobe on a neck, with a tapered binding knob');

    // bold contact marks of the formed complex
    var cop = clamp((e - 0.8) / 0.2);
    if (cop > 0.01) {
      var cg = g.group().opacity(cop);
      var mid = (lx + 15 + rx - 9) / 2;
      cg.line(r1(mid), r1(ly - 68), r1(mid), r1(S + 8))
        .stroke({ color: '#000', width: 3, linecap: 'round' });
      cg.path('M ' + r1(cx - p.CW - 7) + ' ' + r1(S - 1) + ' L ' + r1(cx - p.CW) + ' ' + r1(S - 1) +
        ' L ' + r1(cx - p.CW) + ' ' + r1(S + 8))
        .fill('none').stroke({ color: '#000', width: 3, linecap: 'round', linejoin: 'round' });
      cg.path('M ' + r1(cx + p.CW + 7) + ' ' + r1(S - 1) + ' L ' + r1(cx + p.CW) + ' ' + r1(S - 1) +
        ' L ' + r1(cx + p.CW) + ' ' + r1(S + 8))
        .fill('none').stroke({ color: '#000', width: 3, linecap: 'round', linejoin: 'round' });
      cg.css('cursor', 'pointer')
        .on('mousemove', function (ev) { showTooltip('Contact surfaces of the enzyme–substrate complex', ev); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Enzyme–substrate complex',
            'The bold black lines mark the tight contacts: substrate against substrate in the middle, and each substrate against the rim of the active site. Both models end here — an identical, snugly sealed complex.');
        });
    }

    // annotations on the unbound frame
    if (d.dock) {
      var aOp = clamp(1 - e / 0.45);
      if (aOp > 0.01) {
        var ag = g.group().opacity(aOp);
        ag.line(r1(cx - 44), 28, r1(cx - 70), 60).stroke({ color: C.text, width: 1.1 });
        ag.line(r1(cx + 36), 28, r1(cx + 58), 58).stroke({ color: C.text, width: 1.1 });
        txt(ag, 'Substrates', cx - 4, 22, 20, true);

        var lines = (d.mode === 'fit')
          ? ['Active', 'site', 'changes', 'to fit']
          : ['Active', 'site is', 'proper', 'shape'];
        for (var i = 0; i < lines.length; i++) txt(ag, lines[i], cx - 1, 74 + i * 18, 17, true);

        ag.path('M ' + r1(cx - 34) + ' 138 C ' + r1(cx - 30) + ' 158 ' + r1(cx - 24) + ' 170 ' + r1(cx - 13) + ' 180')
          .fill('none').stroke({ color: C.text, width: 2, linecap: 'round' });
        arrowHead(ag, cx - 13, 180, Math.atan2(10, 11));
        ag.path('M ' + r1(cx + 30) + ' 138 C ' + r1(cx + 27) + ' 158 ' + r1(cx + 22) + ' 170 ' + r1(cx + 13) + ' 180')
          .fill('none').stroke({ color: C.text, width: 2, linecap: 'round' });
        arrowHead(ag, cx + 13, 180, Math.atan2(10, -9));
      }
    }

    var capOp = d.dock ? clamp((e - 0.7) / 0.3) : 1;
    if (capOp > 0.01) {
      var cg2 = g.group().opacity(capOp);
      txt(cg2, 'Substrate', cx, 74, 20, true);
      txt(cg2, 'complex', cx, 96, 20, true);
      txt(cg2, 'formed', cx, 118, 20, true);
    }

    txt(g, 'Enzyme', cx, 300, 20, false);
  }

  /* ---------- render ---------- */
  function renderAll() {
    dyn.clear();
    diagrams.forEach(drawDiagram);

    var aActive = (state.model === 'Lock-and-key');
    var capA = txt(dyn, '(a) Lock-and-key model', 199, 336, 21, false, aActive ? 'bold' : 'normal');
    var capB = txt(dyn, '(b) Induced fit model', 578, 336, 21, false, aActive ? 'normal' : 'bold');
    var ux = aActive ? 199 : 578, uw = aActive ? 200 : 186;
    dyn.rect(uw, 2).move(ux - uw / 2, 342).fill(C.accent).opacity(0.75);

    capA.css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('Lock-and-key: rigid, pre-shaped active site', ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Lock-and-key model',
          'Emil Fischer (1894) proposed that the active site is already exactly complementary to the substrate, like a lock waiting for its key. The enzyme does not change shape: the cleft looks identical before and after binding.');
      });
    capB.css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('Induced fit: flexible site that molds to the substrate', ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Induced fit model',
          'Daniel Koshland (1958) showed that the active site is flexible. The approaching substrate induces a conformational change, so the complementary shape is created during binding — which also strains the substrate and helps catalysis.');
      });
  }

  /* ---------- controls ---------- */
  function setReadout() {
    var el = document.getElementById('deltaReadout');
    if (!el) return;
    el.innerHTML = 'Conformational change on binding: <b>' +
      (state.model === 'Induced fit' ? 'large (site molds)' : 'none (rigid site)') + '</b>';
  }

  window.toggle_modelToggle = function (on) {
    state.model = on ? 'Induced fit' : 'Lock-and-key';
    var n = document.getElementById('modelName');
    if (n) n.textContent = on ? 'Induced fit (b)' : 'Lock-and-key (a)';
    setReadout();
    renderAll();
  };
  window.update_bindingProgress = function (v) { state.progress = v; renderAll(); };
  window.toggle_shapeGhost = function (on) { state.ghost = on; renderAll(); };

  function setProgress(v) {
    var inp = document.getElementById('bindingProgressInput');
    var out = document.getElementById('bindingProgressVal');
    if (inp) inp.value = v;
    if (out) out.value = Math.round(v * 100) / 100;
    state.progress = v;
    renderAll();
  }

  var playing = false, rafId = null, animT = 0, lastTs = 0;
  window.trigger_playBinding = function () {
    playing = !playing;
    var b = document.getElementById('playBtn');
    if (b) b.textContent = playing ? '⏸ Pause binding' : '▶ Play substrate binding';
    if (playing) { animT = 0; lastTs = performance.now(); rafId = requestAnimationFrame(tick); }
    else if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
  };
  function tick(ts) {
    if (!playing) return;
    var dt = (ts - lastTs) / 1000; lastTs = ts;
    animT += dt;
    var cycle = 3.6, ph = animT % cycle;
    setProgress(ph < 2.4 ? Math.round((ph / 2.4) * 100) / 100 : 1);
    rafId = requestAnimationFrame(tick);
  }

  /* ---------- demo steps ---------- */
  var steps = [
    { title: 'The enzyme and its active site', narration: 'A large green enzyme carries a notched cleft on its surface — the active site. Two purple substrate molecules float above it, unbound.', state: { modelToggle: 'Lock-and-key', bindingProgress: 0, shapeGhost: false } },
